const docx = require("docx");
const fs = require("fs");
const path = require("path");

const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  WidthType, AlignmentType, HeadingLevel, PageBreak, BorderStyle,
  ShadingType, TableOfContents, PageNumber, NumberFormat,
  Header, Footer, LevelFormat, Tab, TabStopPosition, TabStopType,
  PositionalTab, PositionalTabAlignment, PositionalTabLeader,
  ImageRun, convertInchesToTwip
} = docx;

// Colors
const PRIMARY = "1B4F72";
const SECONDARY = "2E86C1";
const ACCENT = "E67E22";
const LIGHT_BG = "EBF5FB";
const TABLE_HEADER = "1B4F72";
const TABLE_HEADER_TEXT = "FFFFFF";
const GRAY = "666666";

// Helper functions
function heading1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    children: [new TextRun({ text, bold: true, size: 32, color: PRIMARY, font: "微软雅黑" })],
  });
}

function heading2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 300, after: 150 },
    children: [new TextRun({ text, bold: true, size: 26, color: SECONDARY, font: "微软雅黑" })],
  });
}

function heading3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 200, after: 100 },
    children: [new TextRun({ text, bold: true, size: 22, color: PRIMARY, font: "微软雅黑" })],
  });
}

function bodyText(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 120, line: 360 },
    alignment: opts.align || AlignmentType.JUSTIFIED,
    children: [new TextRun({ text, size: 21, font: "微软雅黑", color: "333333", ...opts })],
  });
}

function bulletItem(text, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullet-list", level },
    spacing: { after: 80, line: 340 },
    children: [new TextRun({ text, size: 21, font: "微软雅黑", color: "333333" })],
  });
}

function emptyLine() {
  return new Paragraph({ spacing: { after: 100 }, children: [] });
}

// Table helpers
function headerCell(text, width) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: { type: ShadingType.CLEAR, fill: TABLE_HEADER, color: TABLE_HEADER },
    verticalAlign: "center",
    children: [new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 60, after: 60 },
      children: [new TextRun({ text, bold: true, size: 20, color: TABLE_HEADER_TEXT, font: "微软雅黑" })],
    })],
  });
}

function dataCell(text, width, opts = {}) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: opts.shading ? { type: ShadingType.CLEAR, fill: opts.shading, color: opts.shading } : undefined,
    verticalAlign: "center",
    children: [new Paragraph({
      alignment: opts.align || AlignmentType.CENTER,
      spacing: { before: 50, after: 50 },
      children: [new TextRun({ text, size: 20, font: "微软雅黑", color: opts.color || "333333", bold: opts.bold || false })],
    })],
  });
}

function makeTable(headers, rows, colWidths) {
  const totalWidth = colWidths.reduce((a, b) => a + b, 0);
  return new Table({
    width: { size: totalWidth, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [
      new TableRow({ children: headers.map((h, i) => headerCell(h, colWidths[i])) }),
      ...rows.map((row, ri) => new TableRow({
        children: row.map((cell, ci) => dataCell(cell, colWidths[ci], {
          shading: ri % 2 === 1 ? LIGHT_BG : undefined,
        })),
      })),
    ],
  });
}

